545	\section{Lines}
546	
547	The question distributions of the classical low individual degree game and of
548	the Pauli basis test (Chapter~\ref{chap:qpbt-test}) sample lines in $\F_q^m$;
549	we record here the definition of lines and their canonical representatives.
550	
551	\begin{definition}[Lines]\label{def:line}
552		A \emph{line} $\ell$ in $\F_q^m$ specified by a pair
553		$(u,v) \in (\F_q^m)^2$ is the subset
554		\begin{equation}\label{eq:line-set}
555			\ell(u,v) = \bigl\{\, u + tv : t \in \F_q \,\bigr\} \subseteq \F_q^m\;.
556		\end{equation}
557		The vector $v$ is called a \emph{direction} of $\ell(u,v)$; the case $v = 0$
558		is explicitly allowed, in which case the line is the singleton $\{u\}$. A
559		line $\ell(u,v)$ is \emph{axis-parallel} if there is a coordinate
560		$i \in \{1, \dots, m\}$ for which $v = e_i$, the $i$-th elementary basis
561		vector of $\F_q^m$; such a line is said to be \emph{parallel to the $i$-th
562		direction}. A line $\ell(u,v)$ is \emph{diagonal} if there exists
563		$i \in \{0, 1, \dots, m-1\}$ such that $v_1 = v_2 = \dots = v_i = 0$ (for
564		$i = 0$ the condition is vacuous, so every line is diagonal).
565	\end{definition}
566	
567	\begin{proposition}\label{prop:line-equiv}
568		\lean{MIPStarRE.QPBT.linePoints_eq_of_mem}
569		\leanok
570		\uses{def:line}
571		Let $u, v \in \F_q^m$. Then for all $u' \in \ell(u,v)$, we have
572		$\ell(u,v) = \ell(u',v)$.
573	\end{proposition}
574	\begin{proof}
575		\leanok
576		\uses{def:line}
577		Fix $u' \in \ell(u,v)$, so $u' = u + tv$ for some $t \in \F_q$. Any
578		$a \in \ell(u,v)$ has the form $a = u + sv = u' + (s - t)v$, so
579		$\ell(u,v) \subseteq \ell(u',v)$. The symmetric argument gives the reverse
580		inclusion.
581	\end{proof}
582	
583	Thus, for a fixed direction, a line is an equivalence class of its points: the
584	pair $(u,v)$ representing it can use any base point on the line. A canonical
585	representation is obtained as follows.
586	
587	\begin{definition}[Canonical representative of a line]\label{def:line-representative}
588		\uses{def:line, def:cl-canonical, prop:line-equiv}
589		Let $\ell$ be a line in direction $v \neq 0$, and let
590		$L^{\mathrm{Ln}}_v : \F_q^m \to \F_q^m$ denote the canonical linear map with
591		the one-dimensional kernel basis $\{v\}$
592		(Definition~\ref{def:cl-canonical}). The \emph{canonical representative of
593		$\ell$} is the point $u_0 \in \F_q^m$ such that
594		\[
595			u_0 = L^{\mathrm{Ln}}_v(u) \qquad \text{for all } u \in \ell\;.
596		\]
597		This is well defined: since the image and kernel of $L^{\mathrm{Ln}}_v$ are
598		complementary, any $u \in \ell$ decomposes uniquely as $u = u_0 + tv$ with
599		$u_0$ in the image, so $u_0 = u - tv \in \ell$ and
600		$L^{\mathrm{Ln}}_v(u_0) = u_0$; moreover any two points of $\ell$ differ by
601		a multiple of $v$ and therefore have the same image under
602		$L^{\mathrm{Ln}}_v$. A line $\ell = \ell(u,v)$ is henceforth canonically
603		represented by the pair $(u_0, v)$. (For $v = 0$, where the singleton
604		$\{u\}$ leaves no independent kernel basis, we take $L^{\mathrm{Ln}}_0$ to
605		be the identity---the canonical linear map with empty kernel basis---so
606		that $u_0 = u$; the source leaves this case implicit.)
607	\end{definition}
