643	\begin{definition}[State space of a linear register]\label{def:lin-reg}
644		\uses{def:complementary}
645		For a set $V$, we write $\C^V$ for the complex vector space of dimension
646		$|V|$, endowed with the canonical orthonormal basis
647		$\{\ket{x}\}_{x \in V}$. A \emph{quantum state on $V$} is a unit vector
648		$\ket{\psi}_V \in \C^V$. If $V = \bigoplus_{i=1}^k V_i$ is a direct sum of
649		subspaces over $\F$, then $\C^V$ is identified with
650		$\bigotimes_{i=1}^k \C^{V_i}$ by identifying
651		$\ket{x_1 \oplus \dots \oplus x_k}$ with
652		$\ket{x_1} \ot \dots \ot \ket{x_k}$. In particular, a basis $\{e_i\}$ of
653		$V$ yields the decomposition $V = \bigoplus_{i=1}^k (\F e_i)$ and hence
654		$\C^V = \bigotimes_{i=1}^k \C^{|\F|}$; the factors $\C^{|\F|}$ are called
655		the \emph{qudits} of $\C^V$.
656	\end{definition}
