658	\begin{definition}[EPR state]\label{def:EPR}
659		\lean{MIPStarRE.QPBT.eprState}
660		\leanok
661		\uses{def:lin-reg}
662		For a linear space $V$ over a finite field $\F$, the \emph{EPR state} on
663		$\C^V \ot \C^V$ is
664		\[
665			\ket{\mathrm{EPR}}_V
666			= \frac{1}{\sqrt{|V|}} \sum_{x \in V} \ket{x} \ot \ket{x}\;.
667		\]
668		We write $\ket{\mathrm{EPR}_q}$ for $\ket{\mathrm{EPR}}_{\F_q}$ and
669		$\ket{\mathrm{EPR}}$ for $\ket{\mathrm{EPR}_2}$.
670	\end{definition}
